package com.InventoryInsights;

import lombok.Getter;

@Getter
public class BoostEntry {
    private final String skill;
    private final double percent;
    private final int base;
    private final boolean restore;

    public BoostEntry(String skill, double percent, int base, boolean restore) {
        this.skill = skill;
        this.percent = percent;
        this.base = base;
        this.restore = restore;
    }
}

package com.InventoryInsights;

import java.util.List;
import lombok.Getter;

@Getter
public class ConsumableEntry {
    private final int heal;
    private final double healPercent;
    private final boolean overheal;
    private final int prayer;
    private final double prayerPercent;
    private final List<BoostEntry> boosts;
    private final String reason;

    public ConsumableEntry(int heal, double healPercent, boolean overheal,
                           int prayer, double prayerPercent,
                           List<BoostEntry> boosts, String reason) {
        this.heal = heal;
        this.healPercent = healPercent;
        this.overheal = overheal;
        this.prayer = prayer;
        this.prayerPercent = prayerPercent;
        this.boosts = boosts;
        this.reason = reason;
    }
}

package com.InventoryInsights;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

@Singleton
public class ConsumableManager {

    private final Map<String, ConsumableEntry> consumables = new HashMap<>();

    @Inject
    public ConsumableManager() {
        init();
    }

    public ConsumableEntry get(String itemName) {
        if (itemName == null) return null;
        return consumables.get(normalizeName(itemName));
    }

    private String normalizeName(String name) {
        String n = name.toLowerCase();
        n = n.replaceAll("\\(\\d\\)", "").trim();
        return n;
    }

    private void register(ConsumableEntry entry, String... names) {
        for (String name : names) {
            consumables.put(normalizeName(name), entry);
        }
    }

    // CONSUMABLE entries for lookup

