    private List<BoostEntry> list(BoostEntry... entries) {
        return Arrays.asList(entries);
    }

    // --- HELPER METHODS ---

    // 1. Boost with Percentage (e.g., 10% + 3)
    private BoostEntry boost(Skill skill, double percent, int base) {
        return new BoostEntry(skill.getName(), percent, base, false);
    }

    // 2. NEW: Flat Boost (no percentage)
    private BoostEntry boost(Skill skill, int base) {
        return new BoostEntry(skill.getName(), 0, base, false);
    }
}

package com.InventoryInsights;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("InventoryInsights")
public interface InventoryInsightsConfig extends Config {

	enum CompareHotkey {
		ALWAYS_ACTIVE, HOLD_CTRL, HOLD_SHIFT, HOLD_ALT, DISABLED
	}

	enum OverlaySide {
		LEFT, RIGHT
	}

	// ==========================================================
	//  SECTIONS
	// ==========================================================

	@ConfigSection(
			name = "General Content",
			description = "Choose what information is displayed.",
			position = 0
	)
	String generalSection = "generalSection";

	@ConfigSection(
			name = "Display & Styling",
			description = "Customize the visual appearance of the overlay.",
			position = 1
	)
	String displaySection = "displaySection";

	@ConfigSection(
			name = "Inventory Interaction",
			description = "Controls for using the plugin in your Inventory.",
			position = 2
	)
	String inventorySection = "inventorySection";

	@ConfigSection(
			name = "Bank Interaction",
			description = "Controls for using the plugin in your Bank.",
			position = 3
