package com.InventoryInsights;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuEntry;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.PanelComponent;

/**
 * Main Controller for the plugin.
 * Handles the game loop (render), detects hovered items,
 * fetches data, and passes it to the PanelBuilder.
 */
public class InventoryInsightsOverlay extends Overlay {

    private final Client client;
    private final ItemManager itemManager;
    private final ConsumableManager consumableManager;
    private final InventoryInsightsConfig config;
    private final PanelBuilder panelBuilder;
    private final OverlayPositioner positioner;

    private final PanelComponent equippedPanel = new PanelComponent();
    private final PanelComponent hoveredPanel = new PanelComponent();

    // --- STATE TRACKING (For Caching) ---
    private int lastHoveredId = -1;
    private int lastQuantity = -1;
    private int lastEquippedId = -1;

    private boolean lastMinimalist = false;
    private Theme lastTheme = null;
    private boolean lastShowMarket = true;
    private boolean lastShowAlch = true;
    private boolean lastShowDose = true;
    private boolean lastShowConsumables = true;

    // Simple helper class to pass ID + Quantity together
    private static class HoverData {
        int id;
        int quantity;
        HoverData(int id, int quantity) { this.id = id; this.quantity = quantity; }
    }

    @Inject
    public InventoryInsightsOverlay(Client client, ItemManager itemManager, ConsumableManager consumableManager,
                                    InventoryInsightsConfig config, PanelBuilder panelBuilder) {
        this.client = client;
        this.itemManager = itemManager;
        this.consumableManager = consumableManager;
        this.config = config;
        this.panelBuilder = panelBuilder;
        this.positioner = new OverlayPositioner(config);

        setPriority(Overlay.PRIORITY_HIGHEST);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPosition(OverlayPosition.DYNAMIC);

        equippedPanel.setBackgroundColor(Theme.STANDARD.getBackgroundColor());
        hoveredPanel.setBackgroundColor(Theme.STANDARD.getBackgroundColor());
    }

    /**
     * Main Render Loop. Runs every frame.
     */
    @Override
    public Dimension render(Graphics2D graphics) {
        if (client.isMenuOpen()) return null;

        applyTheme();

        // 1. Identify the item under the mouse (ID + Stack Size)
        HoverData hoverData = getHoveredItemData();
        if (hoverData == null || hoverData.id == -1) return null;

        boolean isBankOpen = isBankOpen();

        // 2. Check Hotkey constraints (Shift, Ctrl, etc.)
        if (!isHotkeyAllowed(isBankOpen)) {
            lastHoveredId = -1;
            return null;
        }

        Widget referenceWidget = getReferenceWidget(isBankOpen);
        if (referenceWidget == null || referenceWidget.isHidden()) return null;

        // --- DATA COLLECTION ---
        ItemComposition itemComp = itemManager.getItemComposition(hoverData.id);
        ItemStats hStats = itemManager.getItemStats(hoverData.id);

        ConsumableEntry consumable = consumableManager.get(itemComp.getName());
        if (!config.showConsumables()) {
            consumable = null;
        }

        boolean isEquipable = hStats != null && hStats.isEquipable();

        // Check if ANY market feature is enabled
        boolean showMarketData = config.showGE() || config.showHighAlch() || config.showCostPerDose();

        // 3. Gatekeeper: Stop rendering if the item is useless (Not Equipable, Not Consumable, No Market Data)
        if (!isEquipable && consumable == null && !showMarketData) {
            lastHoveredId = -1;
            return null;
        }

        // 4. Fetch Equipped Items (Current Gear, Shield, Weapon) for comparison
        int equippedId = getEquippedItemId(isEquipable, hStats);
        ItemStats eStats = (equippedId != -1) ? itemManager.getItemStats(equippedId) : null;

        int shieldId = -1;
        ItemStats shieldStats = null;
        int weaponId = -1;
        ItemStats weaponStats = null;

        if (isEquipable) {
            ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
            if (equipment != null) {
                // Fetch Shield
                Item shield = equipment.getItem(EquipmentInventorySlot.SHIELD.getSlotIdx());
                if (shield != null) {
                    shieldId = shield.getId();
                    shieldStats = itemManager.getItemStats(shieldId);
                }
                // Fetch Weapon
                Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
                if (weapon != null) {
                    weaponId = weapon.getId();
                    weaponStats = itemManager.getItemStats(weaponId);
                }
            }
        }

        // 5. Update Panels (Only rebuilds if data changed to save performance)
        updatePanelsIfChanged(hoverData.id, hoverData.quantity, hStats, equippedId, eStats, shieldId, shieldStats, weaponId, weaponStats, consumable);

        // 6. Position & Render
        positioner.positionPanels(hoveredPanel, equippedPanel, referenceWidget, isBankOpen, isEquipable);

        if (!config.minimalist() && isEquipable) {
            equippedPanel.render(graphics);
        }
        hoveredPanel.render(graphics);

        return null;
    }

    private void applyTheme() {
        Color currentBg = config.theme().getBackgroundColor();
        equippedPanel.setBackgroundColor(currentBg);
        hoveredPanel.setBackgroundColor(currentBg);
    }

    /**
     * Determines which item is being hovered by checking the Menu Entries.
     * Also fetches the stack size (quantity) from the underlying widget.
     */
    private HoverData getHoveredItemData() {
        MenuEntry[] entries = client.getMenu().getMenuEntries();
        if (entries == null || entries.length == 0) return null;

        MenuEntry entry = entries[entries.length - 1];
        int id = entry.getItemId();
        if (id <= 0) return null;

        int quantity = 1;
        try {
            // Widget Lookup to find Stack Size
            Widget w = client.getWidget(entry.getParam1());
            if (w != null) {
                Widget child = w.getChild(entry.getParam0());
                if (child != null) {
                    quantity = child.getItemQuantity();
                } else {
                    quantity = w.getItemQuantity();
                }
            }
        } catch (Exception ignored) {
            // Fallback to 1
        }

        if (quantity < 1) quantity = 1;

        return new HoverData(id, quantity);
    }

    private boolean isBankOpen() {
        Widget bankWidget = client.getWidget(InterfaceID.BANK, 0);
        return bankWidget != null && !bankWidget.isHidden();
    }

    private boolean isHotkeyAllowed(boolean isBankOpen) {
        InventoryInsightsConfig.CompareHotkey activeKey = isBankOpen ? config.bankCompareHotkey() : config.inventoryCompareHotkey();
        switch (activeKey) {
            case ALWAYS_ACTIVE: return true;
            case HOLD_CTRL:     return client.isKeyPressed(KeyCode.KC_CONTROL);
            case HOLD_SHIFT:    return client.isKeyPressed(KeyCode.KC_SHIFT);
            case HOLD_ALT:      return client.isKeyPressed(KeyCode.KC_ALT);
            case DISABLED:      return false;
            default:            return false;
        }
    }

    private Widget getReferenceWidget(boolean isBankOpen) {
        if (isBankOpen) {
            Widget w = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
            if (w == null || w.isHidden()) {
                w = client.getWidget(InterfaceID.BANK, 0);
            }
            return w;
        } else {
            return client.getWidget(InterfaceID.INVENTORY, 0);
        }
    }

    private int getEquippedItemId(boolean isEquipable, ItemStats hStats) {
        if (!isEquipable || hStats.getEquipment() == null) return -1;
        ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
        if (equipment != null) {
            Item equippedItem = equipment.getItem(hStats.getEquipment().getSlot());
            if (equippedItem != null) return equippedItem.getId();
        }
        return -1;
    }

    /**
     * Checks if any data or config has changed since the last frame.
     * If yes, it triggers the PanelBuilder to rebuild the UI components.
     */
    private void updatePanelsIfChanged(int hId, int hQty, ItemStats hStats,
                                       int eId, ItemStats eStats,
                                       int shieldId, ItemStats shieldStats,
                                       int weaponId, ItemStats weaponStats,
                                       ConsumableEntry consumable) {

        boolean configChanged =
                (config.minimalist() != lastMinimalist)
                        || (config.theme() != lastTheme)
                        || (config.showGE() != lastShowMarket)
                        || (config.showHighAlch() != lastShowAlch)
                        || (config.showCostPerDose() != lastShowDose)
                        || (config.showConsumables() != lastShowConsumables);

        // Include Quantity in change detection so updating stacks works live
        boolean dataChanged = (hId != lastHoveredId) || (hQty != lastQuantity) || (eId != lastEquippedId) || configChanged;

        if (dataChanged) {
            panelBuilder.buildHoverPanel(hoveredPanel, hId, hQty, hStats, eId, eStats, shieldId, shieldStats, weaponId, weaponStats, consumable);

            if (!config.minimalist() && hStats != null && hStats.isEquipable()) {
                panelBuilder.buildEquippedPanel(equippedPanel, eId, eStats);
            } else {
                equippedPanel.getChildren().clear();
            }

            // Update Cache
            lastHoveredId = hId;
            lastQuantity = hQty;
            lastEquippedId = eId;
            lastMinimalist = config.minimalist();
            lastTheme = config.theme();
            lastShowMarket = config.showGE();
            lastShowAlch = config.showHighAlch();
            lastShowDose = config.showCostPerDose();
            lastShowConsumables = config.showConsumables();
        }
    }
}

