package com.InventoryInsights;

public class ItemStatCalculator {

    /**
     * Calculates the actual stat change applied by an item.
     * Handles the complex logic of Boosts (capped at base + boost) vs Restores (capped at base).
     *
     * @param currentLevel The player's current visible level.
     * @param baseLevel    The player's real level (XP-based).
     * @param percent      The percentage amount (e.g., 0.15 for 15%).
     * @param base         The flat amount (e.g., 5).
     * @param isRestore    True if this is a restore potion (e.g., Restore Potion), capping at baseLevel.
     * @return The predicted change in levels (e.g., +19, -5, or 0).
     */
    public static int getEffectiveChange(int currentLevel, int baseLevel, double percent, int base, boolean isRestore) {

        int rawAmount;
        boolean isDrain = (percent < 0 || base < 0);

        // STEP 1: Calculate the Raw Change Amount
        if (isDrain) {
            double p = Math.abs(percent);
            int b = Math.abs(base);
            rawAmount = (int) ((currentLevel * p) + b);
            rawAmount = -rawAmount;
        } else {
            rawAmount = (int) ((baseLevel * percent) + base);
        }

        int targetLevel;

        // STEP 2: Apply Caps and Limits based on Potion Type
        if (isRestore) {
            int potential = currentLevel + rawAmount;

            if (currentLevel >= baseLevel) {
                return 0;
            }
            targetLevel = Math.min(potential, baseLevel);

        } else if (isDrain) {
            targetLevel = Math.max(0, currentLevel + rawAmount);

        } else {
            // --- BOOST LOGIC ---

            int maxPossibleLevel = baseLevel + rawAmount;
            int potential = currentLevel + rawAmount;

            if (currentLevel >= maxPossibleLevel) {
                targetLevel = currentLevel;
            } else {
                targetLevel = Math.min(potential, maxPossibleLevel);
            }
        }


        return targetLevel - currentLevel;
    }
}

