import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

public class OverlayCenteredImage implements LayoutableRenderableEntity {

    private final BufferedImage image;
    private final int width;
    private Point pos = new Point();

    public OverlayCenteredImage(BufferedImage image, int width) {
        this.image = image;
        this.width = width;
    }

    /**
     * Renders the item icon centered within the panel.
     */
    @Override
    public Dimension render(Graphics2D g) {
        if (image == null) return new Dimension(width, 0);

        int centerX = pos.x + (width - image.getWidth()) / 2;

        g.drawImage(image, centerX, pos.y, null);

        return new Dimension(width, image.getHeight());
    }

    @Override public Rectangle getBounds() { return new Rectangle(pos.x, pos.y, width, image.getHeight()); }
    @Override public void setPreferredLocation(Point p) { this.pos = p; }
    @Override public void setPreferredSize(Dimension d) {}
}

