package com.InventoryInsights;

import java.awt.Point;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.components.PanelComponent;

public class OverlayPositioner {

    private final InventoryInsightsConfig config;
    private static final int MIN_WIDTH = 135;

    public OverlayPositioner(InventoryInsightsConfig config) {
        this.config = config;
    }

    /**
     * Calculates the exact X/Y screen coordinates for the overlay panels.
     * It handles:
     * 1. Anchoring to the correct container (Bank vs Inventory).
     * 2. Calculating Left/Right positioning based on user config.
     * 3. Stacking logic for Dual-Panel mode (Comparison vs Single Item).
     */
    public void positionPanels(PanelComponent hoveredPanel, PanelComponent equippedPanel,
                               Widget referenceWidget, boolean isBankOpen, boolean isEquipable) {

        net.runelite.api.Point loc = referenceWidget.getCanvasLocation();
        int spacing = config.overlaySpacing();
        int panelW = hoveredPanel.getBounds().width;
        if (panelW == 0) panelW = MIN_WIDTH;

        int hY = loc.getY() - 30;
        int hX;

        // Determine which side preference to use (Bank and Inventory can be different)
        InventoryInsightsConfig.OverlaySide side;
        if (isBankOpen) {
            side = config.bankOverlaySide();
        } else {
            side = config.inventoryOverlaySide();
        }

        // --- HORIZONTAL ANCHORING ---
        if (side == InventoryInsightsConfig.OverlaySide.RIGHT) {

            hX = loc.getX() + referenceWidget.getWidth() + spacing;
        } else {

            hX = loc.getX() - panelW - spacing;
        }


        if (!isBankOpen) {
            hX -= 20;
        }

        // --- STACKING LOGIC ---
        if (config.minimalist() || !isEquipable) {
            hoveredPanel.setPreferredLocation(new Point(hX, hY));
        } else {
            int eqW = equippedPanel.getBounds().width;
            if (eqW == 0) eqW = MIN_WIDTH;

            if (side == InventoryInsightsConfig.OverlaySide.RIGHT) {
                // Right Side Stack: [Container] -> [Hovered Panel] -> [Equipped Panel]
                hoveredPanel.setPreferredLocation(new Point(hX, hY));
                equippedPanel.setPreferredLocation(new Point(hX + panelW + spacing, hY));
            } else {
                // Left Side Stack: [Equipped Panel] <- [Hovered Panel] <- [Container]
                // Draw the Hovered panel closest to the inventory, and push the Equipped panel further out.
                hoveredPanel.setPreferredLocation(new Point(hX, hY));
                equippedPanel.setPreferredLocation(new Point(hX - eqW - spacing, hY));
            }
        }
    }
}

package com.InventoryInsights;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

public class OverlaySplitText implements LayoutableRenderableEntity {

    private final String leftText;
    private final String rightText;
    private final Color rightColor;
    private final int width;
    private Point pos = new Point();

    public OverlaySplitText(String leftText, String rightText, Color rightColor, int width) {
        this.leftText = leftText;
        this.rightText = rightText;
        this.rightColor = rightColor;
        this.width = width;
    }

    /**
     * Renders two pieces of text centered together as one block.
     * Useful for things like "GE Price: 500 gp" where you want the label white
     * and the value colored, but the whole line centered.
     */
    @Override
    public Dimension render(Graphics2D g) {
        g.setFont(FontManager.getRunescapeSmallFont());

        int leftW = g.getFontMetrics().stringWidth(leftText);
        int rightW = g.getFontMetrics().stringWidth(rightText);
        int totalW = leftW + rightW;

        int startX = pos.x + ((width - 2) - totalW) / 2;
        int y = pos.y + g.getFontMetrics().getAscent();

        g.setColor(Color.WHITE);
        g.drawString(leftText, startX, y);

        g.setColor(rightColor);
        g.drawString(rightText, startX + leftW, y);

        return new Dimension(width, g.getFontMetrics().getHeight());
    }

    @Override public Rectangle getBounds() { return new Rectangle(pos.x, pos.y, width, 12); }
    @Override public void setPreferredLocation(Point p) { this.pos = p; }
    @Override public void setPreferredSize(Dimension d) {}
}

package com.InventoryInsights;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

public class OverlayStatLine implements LayoutableRenderableEntity {

    private final String label;
    private final String mainText;
    private final String subText;
    private final Color subColor;
    private final int width;
    private Point pos = new Point();

    public OverlayStatLine(String label, String mainText, String subText, Color subColor, int width) {
        this.label = label;
        this.mainText = mainText;
        this.subText = subText;
        this.subColor = subColor;
        this.width = width;
    }

    /**
     * Renders a single row of stats.
     * Layout: [Label (Left)] ............ [Main Value][Sub Value (Right)]
     */
    @Override
    public Dimension render(Graphics2D g) {
        g.setFont(FontManager.getRunescapeSmallFont());
        int y = pos.y + g.getFontMetrics().getAscent();

        // 1. Draw the Label aligned to the Left
        g.setColor(Color.WHITE);
        g.drawString(label, pos.x, y);

        // 2. Calculate Right-Side Alignment
        // We need to shift the X position back from the right edge based on the total text width.
        int mainW = g.getFontMetrics().stringWidth(mainText);
        int subW = g.getFontMetrics().stringWidth(subText);

        // Starting X = (Total Panel Width) - (Padding) - (Total Text Width)
        int x = (pos.x + width - 2) - (mainW + subW);

        // 3. Draw Main Value (e.g., "82")
        g.setColor(Color.WHITE);
        g.drawString(mainText, x, y);

        // 4. Draw Sub Value (e.g., "(+4)") immediately after
        // This is colored green/red depending on the 'subColor' passed in.
        if (!subText.isEmpty()) {
            g.setColor(subColor);
            g.drawString(subText, x + mainW, y);
        }

        return new Dimension(width, g.getFontMetrics().getHeight());
    }

    @Override public Rectangle getBounds() { return new Rectangle(pos.x, pos.y, width, 12); }
    @Override public void setPreferredLocation(Point p) { this.pos = p; }
    @Override public void setPreferredSize(Dimension d) {}
}

