import net.runelite.client.ui.overlay.components.PanelComponent;

/**
 * Handles the construction and layout of the overlay panels.
 * This class orchestrates rendering of Item details, Gear Stats, Consumable Effects, and Market Data.
 */
public class PanelBuilder {

    private final Client client;
    private final ItemManager itemManager;
    private final InventoryInsightsConfig config;

    private static final int MIN_WIDTH = 135;
    private static final int NATURE_RUNE_ID = 561;

    @Inject
    public PanelBuilder(Client client, ItemManager itemManager, InventoryInsightsConfig config) {
        this.client = client;
        this.itemManager = itemManager;
        this.config = config;
    }

    /**
     * Entry point for the "Hovered Item" panel.
     * Determines the appropriate Header Title (Comparison, Consumable, or Item).
     */
    public void buildHoverPanel(PanelComponent p, int itemId, int quantity, ItemStats stats,
                                int equippedId, ItemStats compareStats,
                                int shieldId, ItemStats shieldStats,
                                int weaponId, ItemStats weaponStats,
                                ConsumableEntry consumable) {
        p.getChildren().clear();

        // Determine dynamic title based on item type
        String title;
        if (stats != null && stats.isEquipable()) {
            title = "COMPARISON";
        } else if (consumable != null) {
            title = "CONSUMABLE";
        } else {
            title = "ITEM";
        }
        buildPanel(p, itemId, quantity, stats, equippedId, compareStats, shieldId, shieldStats, weaponId, weaponStats, consumable, title, false);
    }

    /**
     * Entry point for the "Equipped Item" panel.
     * Always treats quantity as 1 and hides market/weight comparisons.
     */
    public void buildEquippedPanel(PanelComponent p, int itemId, ItemStats stats) {
        p.getChildren().clear();
        buildPanel(p, itemId, 1, stats, -1, null, -1, null, -1, null, null, "EQUIPPED", true);
    }

    /**
     * Core logic for assembling the UI panel.
     * Stacks components vertically: Name -> Image -> Consumables -> Gear Stats -> Weight -> Market Data.
     */
    private void buildPanel(PanelComponent p, int itemId, int quantity, ItemStats stats,
                            int equippedId, ItemStats compareStats,
                            int shieldId, ItemStats shieldStats,
                            int weaponId, ItemStats weaponStats,
                            ConsumableEntry consumable, String title, boolean isEquippedPanel) {
        boolean isMinimal = config.minimalist();

        if (itemId == -1) {
            if (isEquippedPanel) {
                addCenteredText(p, "EMPTY SLOT", config.theme().getColorNeutral(), MIN_WIDTH);
            }
            return;
        }

        ItemComposition comp = itemManager.getItemComposition(itemId);

        // --- Layout & Dimensions ---
        // Dynamic width calculation based on text length to prevent wrapping issues
        int nameWidth = comp.getName().length() * 7 + 20;
        int reasonWidth = (consumable != null && consumable.getReason() != null) ? consumable.getReason().length() * 6 + 10 : 0;
        int panelWidth = Math.max(MIN_WIDTH, Math.max(nameWidth, reasonWidth));

        // --- Header Section ---
        addCenteredText(p, comp.getName(), Color.WHITE, panelWidth);

        if (!isMinimal) {
            Theme t = config.theme();
            Color titleColor = isEquippedPanel ? t.getColorNeutral() : t.getHeaderOther();
            addCenteredText(p, title, titleColor, panelWidth);

            BufferedImage img = itemManager.getImage(itemId);
            if (img != null) {
                p.getChildren().add(new OverlayCenteredImage(img, panelWidth));
            }
        }

        // --- Consumable Logic ---
        if (consumable != null) {
            renderConsumable(p, consumable, panelWidth);
        }

        // --- Combat Gear Stats ---
        if (stats != null && stats.getEquipment() != null) {
            ItemEquipmentStats s = stats.getEquipment();
            ItemEquipmentStats c = (compareStats != null) ? compareStats.getEquipment() : null;
            ItemEquipmentStats shield = (shieldStats != null) ? shieldStats.getEquipment() : null;
            ItemEquipmentStats weapon = (weaponStats != null) ? weaponStats.getEquipment() : null;

            // 2H Weapon Logic: Detect if equipping this item removes shield/weapon
            boolean removesShield = false;
            boolean removesWeapon = false;

            if (!isEquippedPanel) {
                if (s.isTwoHanded() && shield != null) {
                    removesShield = true;
                }
                if (s.getSlot() == EquipmentInventorySlot.SHIELD.getSlotIdx() &&
                        weapon != null && weapon.isTwoHanded()) {
                    removesWeapon = true;
                }
            }

            renderGearStats(p, s, c, shield, weapon, removesShield, removesWeapon, compareStats != null, panelWidth);
            renderWeight(p, stats, compareStats, shieldStats, weaponStats, removesShield, removesWeapon, !isEquippedPanel, panelWidth);

            // Warnings for 2H conflicts
            if (!isMinimal) {
                if (removesShield) {
                    addCenteredText(p, "(Removes Off-hand)", config.theme().getColorNegative(), panelWidth);
                }
                if (removesWeapon) {
                    addCenteredText(p, "(Removes Main-hand)", config.theme().getColorNegative(), panelWidth);
                }
            }
        }

        // --- Market Data Section ---
        boolean showAnyMarketData = (config.showGE() || config.showHighAlch() || config.showCostPerDose());

        if (showAnyMarketData) {
            renderMarketData(p, itemId, comp.getName(), quantity, panelWidth);
        }
    }

    /**
     * Calculates and renders weight differences, accounting for 2H weapon swapping logic.
     */
    private void renderWeight(PanelComponent p, ItemStats currentStats,
                              ItemStats equippedStats,
                              ItemStats shieldStats,
                              ItemStats weaponStats,
                              boolean removesShield, boolean removesWeapon,
                              boolean showDiff, int width) {
        if (currentStats == null) return;

        double currentKg = currentStats.getWeight();
        double eqKg = 0;

        // Calculate weight of currently equipped items to compare against
        if (showDiff && equippedStats != null) {
            eqKg = equippedStats.getWeight();
            if (removesShield && shieldStats != null) eqKg += shieldStats.getWeight();
            if (removesWeapon && weaponStats != null) eqKg += weaponStats.getWeight();
        }

        String mainText = String.format("%.1f kg", currentKg);
        String subText = "";
        Color subColor = config.theme().getColorNeutral();

        // Calculate difference (Red = Heavier, Green = Lighter)
        if (showDiff && equippedStats != null) {
            double diff = currentKg - eqKg;
            if (Math.abs(diff) > 0.001) {
                String sign = (diff > 0) ? "+" : "";
                subText = String.format(" (%s%.1f)", sign, diff);
                subColor = (diff > 0) ? config.theme().getColorNegative() : config.theme().getColorPositive();
            }
        }
        p.getChildren().add(new OverlayStatLine("Weight", mainText, subText, subColor, width));
    }

    /**
     * Renders Financial Data (GE, High Alch, Potions).
     * Includes special formatting for Coins and Stack calculations.
     */
    private void renderMarketData(PanelComponent p, int itemId, String name, int quantity, int width) {
        // Special Case: Coins (Simple Value display, no Alch/Dose logic)
        if (itemId == ItemID.COINS_995) {
            if (config.showGE()) {
                addHeader(p, "MARKET", config.theme().getHeaderOther(), width);
                String coinText = String.format("%,d gp", quantity);
                addCenteredSplitText(p, "Value: ", coinText, config.theme().getHeaderOther(), width);
            }
            return;
        }

        boolean shouldShowHeader = config.showGE() || config.showHighAlch() || config.showCostPerDose();
        if (shouldShowHeader) {
            addHeader(p, "MARKET", config.theme().getHeaderOther(), width);
        }

        int gePrice = itemManager.getItemPrice(itemId);

        // 1. GE Price (handles Stack vs Single unit display)
        if (config.showGE()) {
            String geText;
            if (quantity > 1) {
                long totalGe = (long) gePrice * quantity;
                geText = formatKMB(totalGe) + " (" + formatKMB(gePrice) + " ea)";
            } else {
                geText = formatKMB(gePrice) + " gp";
            }
            addCenteredSplitText(p, "GE Price: ", geText, config.theme().getHeaderOther(), width);
        }

        // 2. Cost Per Dose (Parses item name for dose count)
        if (config.showCostPerDose()) {
            if (name.contains("(") && name.contains(")")) {
                try {
                    String doseString = name.substring(name.lastIndexOf('(') + 1, name.lastIndexOf(')'));
                    int doses = Integer.parseInt(doseString);

                    if (doses > 0) {
                        int pricePerDose = gePrice / doses;
                        String doseText = formatKMB(pricePerDose) + " gp";
                        addCenteredSplitText(p, "Per Dose: ", doseText, config.theme().getColorNeutral(), width);
                    }
                } catch (NumberFormatException ignored) {}
            }
        }

        // 3. High Alch & Profit Calculation (Alch - Nature Rune - Item Cost)
        if (config.showHighAlch()) {
            ItemComposition itemComp = itemManager.getItemComposition(itemId);
            int alchValue = itemComp.getHaPrice();

            if (alchValue > 0) {
                int natPrice = itemManager.getItemPrice(NATURE_RUNE_ID);
                long unitProfit = alchValue - (gePrice + natPrice);
                long totalAlch = (long) alchValue * quantity;
                long totalProfit = unitProfit * quantity;

                // Alch Value
                String alchText;
                if (quantity > 1) {
                    alchText = formatKMB(totalAlch) + " (" + formatKMB(alchValue) + " ea)";
                } else {
                    alchText = formatKMB(alchValue) + " gp";
                }
                addCenteredSplitText(p, "High Alch: ", alchText, config.theme().getColorNeutral(), width);

                // Net Profit/Loss
                String profitLabel = (totalProfit >= 0) ? "Profit: " : "Loss: ";
                String profitText;
                String sign = (totalProfit > 0) ? "+" : "";

                if (quantity > 1) {
                    profitText = sign + formatKMB(totalProfit) + " (" + sign + formatKMB(unitProfit) + " ea)";
                } else {
                    profitText = sign + formatKMB(totalProfit) + " gp";
                }

                Color profitColor = (totalProfit >= 0) ? config.theme().getColorPositive() : config.theme().getColorNegative();
                addCenteredSplitText(p, profitLabel, profitText, profitColor, width);
            }
        }
    }

    /**
     * Renders Consumable stats (HP, Prayer, Skill Boosts).
     */
    private void renderConsumable(PanelComponent p, ConsumableEntry c, int width) {
        if (!config.showConsumables()) return;
        Color headerColor = config.theme().getHeaderOther();
        addHeader(p, "EFFECTS", headerColor, width);

        // HP & Prayer
        boolean isHpRestore = !c.isOverheal();
        renderEffectLine(p, Skill.HITPOINTS, c.getHealPercent(), c.getHeal(), isHpRestore, width);
        renderEffectLine(p, Skill.PRAYER, c.getPrayerPercent(), c.getPrayer(), true, width);

        // Skill Boosts
        if (c.getBoosts() != null) {
            for (BoostEntry b : c.getBoosts()) {
                try {
                    Skill s = Skill.valueOf(b.getSkill().toUpperCase());
                    renderEffectLine(p, s, b.getPercent(), b.getBase(), b.isRestore(), width);
                } catch (Exception ignored) {}
            }
        }

        // Notes (e.g. "Combo Food")
        if (c.getReason() != null) {
            addSeparator(p);
            String noteText = "Note: " + c.getReason();
            addCenteredText(p, noteText, config.theme().getHeaderOther(), width);
        }
    }

    /**
     * Calculates the effective stat change based on the player's current levels.
     * Shows text even if gain is 0 (e.g., full HP) if the item has a base effect.
     */
    private void renderEffectLine(PanelComponent p, Skill skill, double percent, int base, boolean isRestore, int width) {
        // Filter: If item has no definition for this stat, skip it.
        if (base == 0 && percent == 0) return;

        int curr = client.getBoostedSkillLevel(skill);
        int max = client.getRealSkillLevel(skill);

        // Calculate actual change (capped at max level unless overheal/boost)
        int gain = ItemStatCalculator.getEffectiveChange(curr, max, percent, base, isRestore);

        String gainText = (gain > 0 ? "+" : "") + gain;
        String totalText = " (" + (curr + gain) + ")";
        Theme t = config.theme();

        // Color Logic: Green (Gain), Red (Drain), White (No Change/Capped)
        Color gainColor;
        if (gain > 0) {
            gainColor = t.getColorPositive();
        } else if (gain < 0) {
            gainColor = t.getColorNegative();
        } else {
            gainColor = t.getColorNeutral();
        }

        p.getChildren().add(new OverlayStatLine(skill.getName(), gainText, totalText, gainColor, width));
    }

    /**
     * Renders Combat Stats (Attack, Defence, Bonuses, Speed).
     */
    private void renderGearStats(PanelComponent p, ItemEquipmentStats s, ItemEquipmentStats c,
                                 ItemEquipmentStats shield, ItemEquipmentStats weapon,
                                 boolean removesShield, boolean removesWeapon,
                                 boolean showDiff, int width) {
        Theme t = config.theme();

        // Attack Bonuses
        if (hasStats(s.getAstab(), s.getAslash(), s.getAcrush(), s.getAmagic(), s.getArange())) {
            addHeader(p, "ATTACK", t.getHeaderAttack(), width);
            addStat(p, "Stab", s.getAstab(), c, shield, weapon, removesShield, removesWeapon, "getAstab", showDiff, width);
            addStat(p, "Slash", s.getAslash(), c, shield, weapon, removesShield, removesWeapon, "getAslash", showDiff, width);
            addStat(p, "Crush", s.getAcrush(), c, shield, weapon, removesShield, removesWeapon, "getAcrush", showDiff, width);
            addStat(p, "Magic", s.getAmagic(), c, shield, weapon, removesShield, removesWeapon, "getAmagic", showDiff, width);
            addStat(p, "Range", s.getArange(), c, shield, weapon, removesShield, removesWeapon, "getArange", showDiff, width);
        }

        // Defence Bonuses
        if (hasStats(s.getDstab(), s.getDslash(), s.getDcrush(), s.getDmagic(), s.getDrange())) {
            addHeader(p, "DEFENCE", t.getHeaderDefence(), width);
            addStat(p, "Stab", s.getDstab(), c, shield, weapon, removesShield, removesWeapon, "getDstab", showDiff, width);
            addStat(p, "Slash", s.getDslash(), c, shield, weapon, removesShield, removesWeapon, "getDslash", showDiff, width);
            addStat(p, "Crush", s.getDcrush(), c, shield, weapon, removesShield, removesWeapon, "getDcrush", showDiff, width);
            addStat(p, "Magic", s.getDmagic(), c, shield, weapon, removesShield, removesWeapon, "getDmagic", showDiff, width);
            addStat(p, "Range", s.getDrange(), c, shield, weapon, removesShield, removesWeapon, "getDrange", showDiff, width);
        }

        // Strength & Prayer Bonuses
        if (hasStats(s.getStr(), s.getRstr(), s.getMdmg(), s.getPrayer(), 0)) {
            addHeader(p, "BONUSES", t.getHeaderOther(), width);
            addStat(p, "Melee Str", s.getStr(), c, shield, weapon, removesShield, removesWeapon, "getStr", showDiff, width);
            addStat(p, "Range Str", s.getRstr(), c, shield, weapon, removesShield, removesWeapon, "getRstr", showDiff, width);
            addStat(p, "Magic Dmg", s.getMdmg(), c, shield, weapon, removesShield, removesWeapon, "getMdmg", showDiff, width);
            addStat(p, "Prayer", s.getPrayer(), c, shield, weapon, removesShield, removesWeapon, "getPrayer", showDiff, width);

            renderAttackSpeed(p, s.getAspeed(), c != null ? c.getAspeed() : 0, showDiff, width);
        }
    }

    /**
     * Renders Weapon Speed (in seconds).
     */
    private void renderAttackSpeed(PanelComponent p, double speed, double compSpeed, boolean showDiff, int width) {
        if (speed == 0) return;

        String text = String.format("%.1fs", speed * 0.6);
        String subText = "";
        Color subColor = config.theme().getColorNeutral();

        if (showDiff && compSpeed > 0) {
            double diff = speed - compSpeed;
            if (diff != 0) {
                boolean faster = diff < 0;
                subText = faster ? " (Faster)" : " (Slower)";
                subColor = faster ? config.theme().getColorPositive() : config.theme().getColorNegative();
            }
        }
        p.getChildren().add(new OverlayStatLine("Speed", text, subText, subColor, width));
    }

    /**
     * Helper to render a single stat line with comparison difference calculation.
     */
    private void addStat(PanelComponent p, String label, double val,
                         ItemEquipmentStats c, ItemEquipmentStats shield, ItemEquipmentStats weapon,
                         boolean removesShield, boolean removesWeapon,
                         String methodName, boolean showDiff, int width) {

        double compVal = 0;
        if (c != null) {
            compVal = getStatValue(c, methodName);
            // Adjust comparison value if the new item removes current offhand/mainhand
            if (removesShield && shield != null) compVal += getStatValue(shield, methodName);
            if (removesWeapon && weapon != null) compVal += getStatValue(weapon, methodName);
        }

        if (val == 0 && compVal == 0) return;

        int current = (int) val;
        int diff = (int) (val - compVal);
        String mainText = String.valueOf(current);
        String subText = "";
        Theme t = config.theme();
        Color subColor = t.getColorNeutral();

        if (showDiff && diff != 0) {
            subText = (diff > 0) ? " (+" + diff + ")" : " (" + diff + ")";
            subColor = (diff > 0) ? t.getColorPositive() : t.getColorNegative();
        }

        p.getChildren().add(new OverlayStatLine(label, mainText, subText, subColor, width));
    }

    // --- Reflection/Helper Methods ---

    private double getStatValue(ItemEquipmentStats s, String method) {
        switch (method) {
            case "getAstab": return s.getAstab();
            case "getAslash": return s.getAslash();
            case "getAcrush": return s.getAcrush();
            case "getAmagic": return s.getAmagic();
            case "getArange": return s.getArange();
            case "getDstab": return s.getDstab();
            case "getDslash": return s.getDslash();
            case "getDcrush": return s.getDcrush();
            case "getDmagic": return s.getDmagic();
            case "getDrange": return s.getDrange();
            case "getStr": return s.getStr();
            case "getRstr": return s.getRstr();
            case "getMdmg": return s.getMdmg();
            case "getPrayer": return s.getPrayer();
            default: return 0;
        }
    }

    private boolean hasStats(double... stats) {
        for (double s : stats) if (s != 0) return true;
        return false;
    }

    private void addHeader(PanelComponent p, String title, Color color, int width) {
        if (!config.minimalist()) {
            p.getChildren().add(LineComponent.builder().build());
            addCenteredText(p, title, color, width);
        } else {
            addSeparator(p);
        }
    }

    private void addSeparator(PanelComponent p) {
        p.getChildren().add(LineComponent.builder().left(" ").preferredSize(new Dimension(0, 4)).build());
    }

    private void addCenteredText(PanelComponent p, String text, Color color, int width) {
        p.getChildren().add(new OverlayCenteredText(text, color, width));
    }

    private void addCenteredSplitText(PanelComponent p, String leftLabel, String rightVal, Color rightColor, int width) {
        p.getChildren().add(new OverlaySplitText(leftLabel, rightVal, rightColor, width));
    }

    // --- KMB Formatter (10K, 1.5M) ---
    private String formatKMB(long value) {
        if (value < 0) return "-" + formatKMB(-value);

        if (value >= 1_000_000_000) {
            return String.format("%.1fB", value / 1_000_000_000.0).replace(".0", "");
        } else if (value >= 1_000_000) {
            return String.format("%.1fM", value / 1_000_000.0).replace(".0", "");
        } else if (value >= 1_000) {
            return String.format("%.1fK", value / 1_000.0).replace(".0", "");
        } else {
            return String.valueOf(value);
        }
    }
}

