    private final String name;
    private final Color headerAttack;
    private final Color headerDefence;
    private final Color headerOther;
    private final Color colorPositive;
    private final Color colorNegative;
    private final Color colorNeutral;
    private final Color backgroundColor;

    Theme(String name, Color headerAttack, Color headerDefence, Color headerOther,
          Color colorPositive, Color colorNegative, Color colorNeutral, Color backgroundColor) {
        this.name = name;
        this.headerAttack = headerAttack;
        this.headerDefence = headerDefence;
        this.headerOther = headerOther;
        this.colorPositive = colorPositive;
        this.colorNegative = colorNegative;
        this.colorNeutral = colorNeutral;
        this.backgroundColor = backgroundColor;
    }

    @Override
    public String toString() { return name; }
}

